def pane(pid):
    m = re.search(r'      <div class="pane" role="tabpanel" data-p="%s"[^>]*>.*?\n      </div>\n' % pid, SRC, re.S)
    x = m.group(0).replace(' hidden>', '>').replace(' id="wb-tax"', '')
    x = re.sub(r'<h3>.*?</h3>', '<h2 class="ph2">מקלידים ומקבלים תוצאה</h2>', x, count=1)
    x = re.sub(r' <a href="https://dabullaw.co.il/%d7%94%d7%9e%d7%93%d7%a8%d7%99%d7%9a-%d7%9c%d7%9e%d7%a1[^"]*">המדריך המלא למס רכישה ←</a>', '', x)
    return x
def cite(n): return '<sup><a href="#src-%d">[%d]</a></sup>' % (n, n)
def card(k):
    t, d, slug = CARD[k]
    return '<a class="ccard" href="%s%s/"><span class="ci"><svg viewBox="0 0 24 24" fill="none" stroke="#8a6d2c" stroke-width="1.8">%s</svg></span><b>%s</b><span class="cd">%s</span><span class="go">לחשב ←</span></a>' % (BASE, slug, ICON[k], t, d)

