def build(pg):
    url = BASE + pg['slug'] + '/'
    srcs = [S[k] for k in pg['src']]
    secs = ''.join('<section class="art"><h2>%s</h2>%s</section>' % s for s in pg['sec'])
    a_id, a_t = pg['art']
    relart = '<div class="relart">רוצים להבין את כל התמונה? <a href="%s">%s ←</a></div>' % (ART[a_id], a_t)
    faq = '<section class="art"><h2>שאלות נפוצות</h2>' + ''.join('<details><summary>%s</summary><p>%s</p></details>' % f for f in pg['faq']) + '</section>'
    rel = '<section><div class="sh"><div><p class="k">עוד מחשבונים</p><h2>מחשבונים קשורים</h2></div></div><div class="rel">' + ''.join(card(k) for k in pg['rel']) + '</div></section>'
    cta = '<section><div class="ctab"><div><b>רוצים שנבדוק את המספרים שלכם?</b><p>נעבור על העסקה, על החוזה ועל המס, ונגיד לכם מה כדאי לעשות. 09-8613413</p></div><a href="/%D7%A6%D7%A8%D7%95-%D7%A7%D7%A9%D7%A8/">לשיחה עם עו״ד יקיר דבול ←</a></div></section>'
    src = '<section class="art srcs"><h2>מקורות</h2><ol>' + ''.join('<li id="src-%d"><a href="%s" target="_blank" rel="noopener noreferrer">%s</a>, <em>%s</em></li>' % (i + 1, u, t, s) for i, (u, t, s) in enumerate(srcs)) + '</ol><p>החישוב הוא הערכה כללית ואינו ייעוץ משפטי. המספרים הסופיים תלויים בפרטי העסקה.</p></section>'
    schema = {"@context": "https://schema.org", "@graph": [
        {"@type": "WebApplication", "@id": url + "#app", "name": pg['h1'], "url": url, "applicationCategory": "FinanceApplication", "operatingSystem": "Any", "inLanguage": "he-IL", "isAccessibleForFree": True, "isPartOf": {"@id": url}, "provider": {"@id": "https://dabullaw.co.il/#organization"}},
        {"@type": "FAQPage", "@id": url + "#faq", "isPartOf": {"@id": url}, "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": ans}} for q, ans in pg['faq']]}]}
    body = ('<div class="dt3" dir="rtl">'
            '<p class="crumb"><a href="/">דף הבית</a> › <a href="/calculators/">מחשבונים וכלים</a> › %s</p>' % CARD[pg['id']][0] +
            '<header class="chead"><p class="k">מחשבונים לעסקת דירה</p><h1>%s</h1><p class="ans">%s</p></header>' % (pg['h1'], pg['ans']) +
            '<div class="calcbox">' + pane(pg['id']) + '</div>' + relart + secs + faq + rel + cta + src + '</div>')
    return body, schema

if __name__ == '__main__':
    import os
    os.makedirs(SP + 'hub5/pages', exist_ok=True)
    meta = []
    for pg in PAGES:
        body, schema = build(pg)
        html = STYLE + EXTRA + body + '<script type="application/ld+json">' + json.dumps(schema, ensure_ascii=False) + '</script>'
        open(SP + 'hub5/pages/%s.html' % pg['slug'], 'w', encoding='utf8').write(html)
        txt = H.unescape(re.sub(r'<script.*?</script>|<style.*?</style>|<[^>]+>', ' ', body, flags=re.S))
        meta.append({'slug': pg['slug'], 'title': pg['h1'], 'ytitle': pg['ytitle'], 'ydesc': pg['ydesc'], 'words': len(txt.split()), 'art': pg['art'][0]})
        assert '—' not in html and '–' not in html, pg['slug']
    json.dump(meta, open(SP + 'hub5/pages/meta.json', 'w', encoding='utf8'), ensure_ascii=False, indent=1)
    for m in meta: print(m['slug'], m['words'], len(m['ytitle']), len(m['ydesc']))
